  log('[startOperation] create operation %s (type=%s, context=%o)', operationId, type, context);

  const abortController = new AbortController();
  const now = Date.now();

  const operation: Operation = {
    id: operationId,
    type,
    status: 'running',
    context,
    abortController,
    metadata: {
      startTime: now,
      ...metadata,
    },
    parentOperationId,
    childOperationIds: [],

